  }

  function findSuggestion(missingProperty) {
    let bestMatch = null;
    let bestDistance = Infinity;

    for (const prop of availableProperties) {
      const dist = levenshteinDistance(missingProperty, prop);
      if (dist <= 3) {
        if (dist < bestDistance) {
          bestDistance = dist;
          bestMatch = prop;
        } else if (dist === bestDistance && (bestMatch === null || prop < bestMatch)) {
          bestMatch = prop;
        }
      }
    }

    return bestDistance <= 3 ? bestMatch : null;
  }

  return {
    diagnoseMissingProperty(propertyName) {
      const availableProperties = Object.keys(viewModel).sort();
      const suggestion = findSuggestion(propertyName);

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: suggestion
      };
    }
  };
}

module.exports = { createDebugHelper };
```

